with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('holde sig i ro', 'phrase', 'b6b808e9-f5fc-5a8f-93f6-abcaf364bd47', 1, 'verb', null, 'залишатися нерухомим (не рухатися)', 'Du skal holde dig i ro, mens lægen undersøger dit ben.', 'Ви повинні залишатися нерухомим, поки лікар оглядає вашу ногу.'), ('holde sig i ro', 'phrase', '1ac23773-7b30-5a0a-abc7-a56cfe72c691', 2, 'verb', null, 'відпочивати, не перенапружуватися', 'Efter operationen skal du holde dig i ro i et par dage.', 'Після операції ви повинні відпочивати кілька днів.'), ('afholde sig fra', 'phrase', '26ab67a8-bae4-5fd2-81f9-c7787d8626ac', 1, 'verb', null, 'утримуватися (від чогось)', 'Jeg prøver at afholde mig fra slik i hverdagene.', 'Я намагаюся утримуватися від солодощів у будні.'), ('få besked om', 'phrase', 'ff5bc483-ccea-5d9c-890c-1ac3b6bba8c1', 1, 'verb', null, 'отримувати вказівку (зробити щось)', 'Jeg fik besked om at vente udenfor.', 'Мені сказали чекати зовні.'), ('byde velkommen', 'phrase', '9dda97c2-cf37-5425-a902-7036de76a42d', 1, 'verb', null, 'вітати (гостя)', 'De byder velkommen ved døren.', 'Вони вітають гостей біля дверей.'), ('smage af', 'phrase', '13430617-7976-51ff-8ccb-871653f54871', 1, 'verb', null, 'мати смак (чогось)', 'Kagen smager af citron.', 'Торт має лимонний смак.'), ('sove ind', 'phrase', '6ca71b83-6b66-52e1-9cbd-fde55bddc36d', 1, 'verb', null, 'померти (мирно, уві сні)', 'Min gamle nabo sov ind i nat.', 'Мій старий сусід помер минулої ночі.'), ('sove ud', 'phrase', 'bfc2b234-9dbf-5d2d-bfa2-6e92787b252d', 1, 'verb', null, 'виспатися', 'Jeg sov ud i morges.', 'Сьогодні вранці я виспався.'), ('kaste et blik', 'phrase', 'ef6a0e29-ab34-568a-8233-63d8e6684f4c', 1, 'verb', null, 'кинути погляд', 'Han kastede et blik på uret.', 'Він глянув на годинник.'), ('kaste et blik på', 'phrase', '9e1e6008-0708-54c5-9311-fea427d222c8', 1, 'verb', null, 'кинути погляд на', 'Han kastede et blik på uret og skyndte sig videre.', 'Він глянув на годинник і поспішив далі.'), ('modsætte sig', 'phrase', '18105953-f518-56af-aab2-4041e9d87ed1', 1, 'verb', null, 'заперечувати, противитися', 'Hun modsætter sig altid nye regler på arbejdet.', 'Вона завжди виступає проти нових правил на роботі.'), ('holde mund', 'phrase', '1fb0baa3-5395-550a-8ffc-c5dfad53bde9', 1, 'verb', null, 'мовчати, замовкнути', 'Han bad børnene holde mund under filmen.', 'Він попросив дітей помовчати під час фільму.'), ('sove som en sten', 'phrase', 'fdaefabf-6a06-5831-9f13-fe07bfa8882b', 1, 'verb', null, 'спати дуже міцно (як убитий)', 'Jeg sov som en sten hele natten.', 'Я всю ніч спав як убитий.'), ('tiltrække sig', 'phrase', '284d241e-6c61-5809-8cdd-cfbe85169a04', 1, 'verb', null, 'привертати (увагу)', 'Hendes nye kjole tiltrækker sig meget opmærksomhed.', 'Її нова сукня привертає багато уваги.'), ('en stor tjeneste', 'phrase', 'cf44a265-de4d-5948-8a5f-b711100a7d9f', 1, 'phrase', null, 'велика послуга', 'Kan du gøre mig en stor tjeneste og hente børnene i dag?', 'Можеш зробити мені велику послугу і забрати дітей сьогодні?'), ('gøre tjeneste', 'phrase', 'd049ecb8-06ae-5a5a-a99d-31c501b9840c', 1, 'verb', null, 'служити (в армії)', 'Min bror gør tjeneste i hæren lige nu.', 'Мій брат зараз служить в армії.'), ('gøre tjeneste', 'phrase', '91ed7bc0-d08b-5939-b875-c55353ea4d72', 2, 'verb', null, 'виконувати функцію', 'Den gamle sofa gør tjeneste som seng.', 'Старий диван слугує ліжком.'), ('gøre grin med', 'phrase', '9e6566e3-a905-5890-8402-0a7f58dfecc8', 1, 'verb', null, 'насміхатися з', 'De andre børn gjorde grin med hans nye frisure.', 'Інші діти насміхалися з його нової зачіски.'), ('sænke sig', 'phrase', 'a6434e30-cabd-5246-b428-0b88d3c24d84', 1, 'verb', null, 'опускатися, знижуватися', 'Tågen sænkede sig langsomt over marken.', 'Туман повільно опускався над полем.'), ('stride med', 'phrase', 'f64d66df-a234-5906-9c22-6698d1fd3591', 1, 'verb', null, 'боротися з (труднощами)', 'Hun strider med lektierne hver aften.', 'Щовечора вона мучиться з домашніми завданнями.'), ('kredse om', 'phrase', '8104dc6f-5f0b-5686-a26c-9c92644a7d92', 1, 'verb', null, 'обертатися навколо (теми)', 'Samtalen kredsede om vejret hele aftenen.', 'Розмова весь вечір крутилася навколо погоди.'), ('kredse rundt', 'phrase', 'bef07b60-b152-523d-b87d-7991ec01ad2d', 1, 'verb', null, 'обертатися навколо (чогось)', 'Månen kredser rundt om jorden hele tiden.', 'Місяць постійно обертається навколо Землі.'), ('være fan af', 'phrase', 'c09bd221-e64d-5b77-9cb5-82ca3a7d86d9', 1, 'verb', null, 'бути шанувальником', 'Jeg er fan af den nye film.', 'Я фанат нового фільму.'), ('skrue op', 'phrase', '3b69ba29-e8aa-5012-8008-ebfcb1c8784b', 1, 'verb', null, 'збільшувати (гучність, інтенсивність)', 'Han skruer op for musikken om aftenen.', 'Ввечері він робить музику гучнішою.'), ('skrue op for', 'phrase', '776df6fb-dc48-5f03-a120-98902dab4553', 1, 'verb', null, 'збільшувати (гучність, потужність)', 'Hun skruer op for musikken i stuen.', 'Вона робить музику гучнішою у вітальні.'), ('betale forud', 'phrase', '11758c72-0de7-5cb7-9195-1a350beaf673', 1, 'verb', null, 'платити наперед', 'Du skal betale forud for opholdet.', 'Ви повинні заплатити за проживання наперед.'), ('bøde på', 'phrase', 'e9322329-7220-5aae-beb4-c5a941d10c7f', 1, 'verb', null, 'виправляти (недолік)', 'Han bøder på sin manglende erfaring med hårdt arbejde.', 'Він компенсує брак досвіду важкою працею.'), ('grine sig halvt ihjel', 'phrase', '5968563b-a914-5e99-8cd1-93c91aaae801', 1, 'verb', null, 'вмирати зі сміху', 'Vi grinede os halvt ihjel over den sjove film.', 'Ми мало не померли зі сміху над цим смішним фільмом.'), ('råde over', 'phrase', 'dac37b8c-2edf-59ea-a197-e872dbd11b9e', 1, 'verb', null, 'мати у розпорядженні', 'Vi råder over tre mødelokaler på kontoret.', 'У нашому розпорядженні є три кімнати для зустрічей в офісі.'), ('spille falsk', 'phrase', '2f0b3359-da1a-5746-b34b-7898641344d2', 1, 'verb', null, 'шахраювати (у грі)', 'Han spiller falsk når vi spiller kort.', 'Він шахраює, коли ми граємо в карти.'), ('synge falsk', 'phrase', '71615f91-63d2-54e3-b44a-7204af589be7', 1, 'verb', null, 'фальшивити (співати не в тон)', 'Hun synger falsk hver gang hun prøver.', 'Вона співає фальшиво щоразу, коли намагається.'), ('tage i betragtning', 'phrase', 'e7d6bd5a-e57a-5ae3-baa6-28fe5eabbdf4', 1, 'verb', null, 'брати до уваги', 'Vi skal tage i betragtning, at priserne er steget.', 'Ми повинні враховувати, що ціни зросли.'), ('standse ved', 'phrase', '0f5e8446-3e5b-5084-9130-de8c45d99e87', 1, 'verb', null, 'зупинятися біля', 'Bussen standser ved stationen hver morgen.', 'Автобус зупиняється на станції щоранку.'), ('beklage sig', 'phrase', 'e678a06b-255c-5611-b66b-33d2f8355cea', 1, 'verb', null, 'скаржитися', 'Hun beklager sig altid over vejret.', 'Вона завжди скаржиться на погоду.'), ('tilpasse sig', 'phrase', '760382ec-fd3e-559d-a625-575d7396acf5', 1, 'verb', null, 'пристосовуватися', 'Dyret tilpasser sig langsomt det nye miljø.', 'Тварина поступово пристосовується до нового середовища.'), ('have en affære', 'phrase', '0f50d1f4-024b-56c0-a2c7-987905d89c5d', 1, 'verb', null, 'мати інтрижку (роман на стороні)', 'Hun har en affære med sin kollega.', 'У неї роман з колегою.'), ('være arbejdsløs', 'phrase', 'dbbd758c-5a14-546d-bc4b-e06d219f9b30', 1, 'verb', null, 'бути безробітним', 'Han er arbejdsløs lige nu.', 'Зараз він безробітний.'), ('forsikre sig om', 'phrase', 'bba8ac43-2a71-5169-89e7-a4ac80e98571', 1, 'verb', null, 'переконатися (перевіривши)', 'Jeg forsikrer mig om, at døren er låst, inden jeg går i seng.', 'Я переконуюся, що двері замкнені перед сном.'), ('skride frem', 'phrase', 'b57bcba3-7ae6-5bb1-8a88-5f94a2238407', 1, 'verb', null, 'просуватися (про процес)', 'Byggeriet skrider frem efter planen.', 'Будівництво просувається за планом.'), ('dyrke motion', 'phrase', '1aeda231-43a3-53d3-ae14-b7c88c9dcd6f', 1, 'verb', null, 'займатися спортом (фізичними вправами)', 'Jeg dyrker motion hver morgen før arbejde.', 'Я займаюся спортом щоранку перед роботою.'), ('hygge sig', 'phrase', '66a6f588-48df-51ae-883d-4d5a9b150af8', 1, 'verb', null, 'затишно й приємно проводити час, насолоджуватися спілкуванням', 'Vi hygger os altid med et glas vin om aftenen.', 'Ми завжди затишно проводимо час разом за келихом вина ввечері.'), ('synke ned', 'phrase', 'fed971a6-07c6-5ffd-a6c5-7430045e85ca', 1, 'verb', null, 'опускатися, занурюватися (в рідину або м’яку субстанцію)', 'Stenen synker ned i vandet.', 'Камінь занурюється у воду.'), ('rende væk', 'phrase', '55fc6ab9-3ee9-5ed0-81c9-9c34950e87ae', 1, 'verb', null, 'тікати', 'Hunden rendte væk, da den så katten.', 'Собака втекла, побачивши кота.'), ('smutte forbi', 'phrase', 'fb37c36c-8ec6-58a1-b4da-f6a1f2da8cec', 1, 'verb', null, 'заскочити ненадовго', 'Jeg smutter forbi bageren på vej hjem.', 'Я завітаю до пекарні по дорозі додому.'), ('klæde sig ud som', 'phrase', '35f289fb-eefe-5f49-b079-841e09a57f28', 1, 'verb', null, 'перевдягатися (у костюм) кимось', 'Hun klædte sig ud som en pirat til fastelavn.', 'Вона вбралася піратом на Масляну.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0010' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
